using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ApplyEffectDrawDieAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/ApplyEffectDrawDie Action")]
public class ApplyEffectDrawDieAction : BattleAction
{
	[Header("Purify Gain Status Die Action")]
	[SerializeField]
	private BattleAction effectAction;

	[SerializeField]
	private DrawAction drawAction;

	[SerializeField]
	private int drawDiceAmount;

	[SerializeField]
	private bool usedAmountForDraw;

	[SerializeField]
	private bool invertDescriptions;

	public BattleAction EffectAction => effectAction;

	public DrawAction DrawAction => drawAction;

	public int DrawDiceAmount => drawDiceAmount;

	public bool UsedAmountForDraw => usedAmountForDraw;

	public bool InvertDescriptions => invertDescriptions;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		drawAction.CastAmount(usedAmountForDraw ? amount : drawDiceAmount, source);
		effectAction.CastTargetAmount(target, usedAmountForDraw ? drawDiceAmount : amount, source);
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
	}

	public override void CastAmount(int amount, GameObject source)
	{
		drawAction.CastAmount(usedAmountForDraw ? amount : drawDiceAmount, source);
		effectAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, usedAmountForDraw ? drawDiceAmount : amount, source);
		SpawnVFX(GetVFXOwnerPosition(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
	}
}
